function renderPlanCard(){const status=billing?.status||company.subscriptionStatus||(localTrialDays()>0?'Trial':'Trial ended'),planName=billing?.planName||String(company.plan||'Starter').replace(/^./,letter=>letter.toUpperCase()),days=billing?.daysRemaining??localTrialDays(),trial=status==='Trial';$('#plan-name').textContent=`${planName.toUpperCase()} PLAN`;$('#trial-days').textContent=trial?(days===1?'1 day remaining':`${days} days remaining`):status;$('#trial-progress').style.width=trial?`${Math.max(0,Math.min(100,days/14*100))}%`:(status==='Active'?'100%':'0%');$('#manage-plan').hidden=currentRole==='field'}
function renderBilling(){if(!billing)return;const value=value=>value==null?'Unlimited':value;$$('[data-billing-cycle]').forEach(button=>button.classList.toggle('active',button.dataset.billingCycle===billingCycle));$('#billing-summary').innerHTML=`<div><small>Current plan</small><strong>${helpEscape(billing.planName)}</strong></div><div><small>Status</small><strong>${helpEscape(billing.status)}</strong></div><div><small>Active users</small><strong>${billing.usage.users} / ${value(billing.limits.users)}</strong></div><div><small>Active projects</small><strong>${billing.usage.activeProjects} / ${value(billing.limits.activeProjects)}</strong></div>`;$('#billing-plans').innerHTML=billing.plans.map(plan=>{const annual=billingCycle==='annual',available=annual?plan.annualAvailable:plan.available,price=annual?plan.annualPrice:plan.price;return `<article class="billing-plan ${plan.id===billing.plan?'current':''}"><h3>${helpEscape(plan.name)}</h3><div class="billing-price">$${price}<small>/${annual?'year':'month'}</small></div>${annual?'<small>Two months free</small>':''}<ul><li>Up to ${plan.maxUsers} active users</li><li>${plan.maxProjects==null?'Unlimited':`Up to ${plan.maxProjects}`} active projects</li><li>Free subcontractor guest links</li></ul><button type="button" class="${plan.id===billing.plan&&billing.billingCycle===billingCycle?'secondary':'primary'}" data-plan-checkout="${plan.id}" ${plan.id===billing.plan&&billing.hasSubscription&&billing.billingCycle===billingCycle?'disabled':''}>${plan.id===billing.plan&&billing.hasSubscription&&billing.billingCycle===billingCycle?'Current plan':billing.configured&&available?'Choose plan':'Connect Stripe to activate'}</button></article>`}).join('');$$('[data-plan-checkout]').forEach(button=>button.onclick=()=>startCheckout(button.dataset.planCheckout));$('#billing-portal').hidden=!billing.hasSubscription}
