function dashboardProduction(period='This week'){const now=new Date(),month=period==='This month',start=month?new Date(now.getFullYear(),now.getMonth(),1):new Date(now.getFullYear(),now.getMonth(),now.getDate()-((now.getDay()+6)%7)),labels=month?['W1','W2','W3','W4','W5']:['MON','TUE','WED','THU','FRI'],groups=labels.map(()=>({earned:0,actual:0}));for(const report of reports.filter(row=>row.status==='Approved'&&row.dateIso)){const date=new Date(`${report.dateIso}T12:00:00`);if(date<start||date>now)continue;const group=month?Math.min(4,Math.floor((date.getDate()-1)/7)):(date.getDay()+6)%7;if(group<0||group>=groups.length)continue;const project=projects[report.project],entries=report.productionEntries||[],reportLabor=(report.laborEntries||[]).reduce((sum,row)=>sum+Number(row.hours||0),0);entries.forEach(entry=>{const item=(project?.estimateItems||[]).find(row=>row.id===entry.estimateItemId),rate=item&&Number(item.plannedQuantity)>0?Number(item.budgetHours||0)/Number(item.plannedQuantity):0;groups[group].earned+=Number(entry.quantity||0)*rate;groups[group].actual+=Number(entry.laborHours||0)||(entries.length===1?reportLabor:0)})}const earned=groups.reduce((sum,row)=>sum+row.earned,0),actual=groups.reduce((sum,row)=>sum+row.actual,0);return{labels,groups,efficiency:actual>0?earned/actual*100:null}}
function renderChart(){const period=$('#period-select')?.value||'This week',metrics=dashboardProduction(period),values=metrics.groups.map(row=>row.actual>0?row.earned/row.actual*100:null),scale=Math.max(100,...values.filter(Number.isFinite));$('#production-chart').innerHTML=values.map((value,i)=>`<div class="chart-day"><i class="bar estimate" style="height:${100/scale*100}%" title="Estimated production: 100%"></i><i class="bar actual" style="height:${value==null?0:Math.min(100,value/scale*100)}%" title="${value==null?'No approved production':`Actual production: ${value.toFixed(1)}%`}"></i><label>${metrics.labels[i]}</label></div>`).join('');const summary=$('#dashboard-page .chart-summary strong'),trend=$('#dashboard-page .chart-summary .trend');if(summary)summary.textContent=metrics.efficiency==null?'—':`${metrics.efficiency.toFixed(1)}%`;if(trend){trend.textContent=metrics.efficiency==null?'No approved labor':`${metrics.efficiency>=100?'+':''}${(metrics.efficiency-100).toFixed(1)}%`;trend.className=`trend ${metrics.efficiency!=null&&metrics.efficiency>=100?'metric-good':''}`}}
