const openProjectEstimateView=openProject;
openProject=async function(id){
  openProjectEstimateView(id);
  const project=projects.find(item=>item.id===id);
  if(currentRole!=='office'||!project||!['tm','hybrid'].includes(project.contractType))return;
  try{
    const summary=await api(`/api/projects/${id}/tm-summary`),label=project.contractType==='tm'?'Time & material':'Hybrid';
    const rows=summary.labor.length?summary.labor.map(row=>`<div class="tm-labor-row"><strong>${row.classification}</strong><span>${row.hours.toLocaleString()} hrs × $${row.rate.toLocaleString()}</span><strong>$${row.amount.toLocaleString()}</strong></div>`).join(''):'<div class="estimate-empty">Approved daily labor will appear here.</div>';
    $('#project-detail-content').insertAdjacentHTML('beforeend',`<section class="tm-summary"><div class="estimate-header"><div><h3>${label} summary</h3><small>Verified totals from approved daily reports only</small></div><span class="contract-type">${label}</span></div><div class="tm-summary-grid"><div><small>APPROVED DAILIES</small><strong>${summary.approvedDailies}</strong></div><div><small>LABOR HOURS</small><strong>${summary.laborHours.toLocaleString()}</strong></div><div><small>LABOR VALUE</small><strong>$${summary.laborAmount.toLocaleString()}</strong></div><div><small>MATERIAL / EQUIPMENT LOGS</small><strong>${summary.materialEntries} / ${summary.equipmentEntries}</strong></div></div><div class="tm-labor-row"><small>CLASSIFICATION</small><small>HOURS & RATE</small><small>AMOUNT</small></div>${rows}<small>Material markup: ${summary.materialMarkup}% · Equipment markup: ${summary.equipmentMarkup}%</small></section>`);
  }catch(error){notify(error.message)}
}

const openProjectTmView=openProject;
openProject=async function(id){
  await openProjectTmView(id);
  if(currentRole!=='office')return;
  try{
    const changes=await api(`/api/changes?projectId=${id}`),approved=changes.filter(change=>change.status==='Approved').reduce((sum,change)=>sum+Number(change.amount||0),0);
    const rows=changes.length?changes.map(change=>`<div class="change-row"><strong>${change.number}</strong><span>${change.title}</span><input type="number" min="0" step="0.01" value="${Number(change.amount||0)}" data-change-amount="${change.id}" aria-label="Change amount"><select data-change-status="${change.id}">${['Potential','Submitted','Approved','Rejected','Void'].map(status=>`<option ${status===change.status?'selected':''}>${status}</option>`).join('')}</select></div>`).join(''):'<div class="estimate-empty">No potential changes have been opened for this project.</div>';
    $('#project-detail-content').insertAdjacentHTML('beforeend',`<section class="change-summary"><div class="estimate-header"><div><h3>Changes & extra work</h3><small>${changes.length} tracked · $${approved.toLocaleString()} approved</small></div></div>${rows}</section>`);
    $$('[data-change-status]').forEach(select=>select.onchange=async()=>{const changeId=+select.dataset.changeStatus,amount=+$(`[data-change-amount="${changeId}"]`).value;try{await api(`/api/changes/${changeId}`,{method:'PATCH',body:JSON.stringify({status:select.value,amount})});notify('Change record updated');openProject(id)}catch(error){notify(error.message)}});
  }catch(error){notify(error.message)}
}

